contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner) internal {
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool reverted;
        bool returned;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
            returned = ok;
        } catch {
            reverted = true;
            returned = false;
        }
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        assertTrue(reverted ? (ownerBefore != address(this) && ownerAfter == ownerBefore) : (ownerAfter == newOwner && returned == true));
    }

